// Asocks (https://docs.asocks.com): a port of the account keeps its IP until this asks for
// another one. Needs ASOCKS_API_KEY in the command environment; ASOCKS_SOCKS=1 writes the port as
// SOCKS instead of HTTP.
const key = env.ASOCKS_API_KEY;
if (!key) {
    throw new Error("Set ASOCKS_API_KEY in the command environment");
}

const api = (path, body) => fetch(
    "https://api.asocks.com/v2/" + path + (path.indexOf("?") < 0 ? "?" : "&") + "apiKey=" + encodeURIComponent(key),
    body ? { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) } : undefined
).then(r => r.json());

// The listing is where a port's endpoint, its credentials and the IP it exits from all come from
const readPorts = async () => {
    const answer = await api("proxy/ports?per_page=100");
    const proxies = (answer.message && answer.message.proxies) || [];
    return proxies.filter(p => p.id > 0 && p.proxy);
};

const write = (port) => {
    const scheme = env.ASOCKS_SOCKS === "1" ? "socks5" : "http";
    chan.setProxy(scheme + "://" + encodeURIComponent(port.login || "") + ":" +
        encodeURIComponent(port.password || "") + "@" + port.proxy);
};

const ports = await readPorts();
if (!ports.length) {
    throw new Error("The account holds no proxy ports: buy one on the Asocks dashboard");
}

// The endpoint this forum is already on, which is the port to ask about -- host:port, credentials off
const current = chan.getProxy();
const endpoint = current ? current.replace(/^[a-z0-9]+:\/\//i, "").replace(/^.*@/, "") : null;
let port = endpoint ? ports.find(p => p.proxy === endpoint) : null;
if (!port) {
    // No port of this account is written here yet, so giving the forum one is the change to make
    port = ports[0];
    write(port);
    return "port " + port.id + (port.externalIp ? " · " + port.externalIp : "");
}

const answer = await api("proxy/refresh/" + port.id);
if (!answer.success) {
    throw new Error(answer.message || "Asocks would not change the IP");
}
// The endpoint stays put, but the credentials behind it may not, so write what the listing says now
const after = (await readPorts()).find(p => p.id === port.id) || port;
write(after);
return "port " + after.id + (after.externalIp ? " · " + after.externalIp : " · changed");
